import 'package:flutter_test/flutter_test.dart';\r\nimport 'package:stylehub/models/branch_model.dart';\r\n\r\nvoid main() {\r\n  group('BranchModel Tests', () {\r\n    test('fromMap and toMap serialization', () {\r\n      final map = {\r\n        'name': 'Downtown StyleHub',\r\n        'city': 'New York',\r\n        'address': '123 Main St',\r\n        'phone': '1234567890',\r\n        'imageUrl': 'http://image.com',\r\n        'openingHours': {'Monday': '09:00-18:00'},\r\n      };\r\n\r\n      final branch = BranchModel.fromMap(map, 'test_id');\r\n\r\n      expect(branch.id, 'test_id');\r\n      expect(branch.name, 'Downtown StyleHub');\r\n      expect(branch.city, 'New York');\r\n      expect(branch.address, '123 Main St');\r\n      expect(branch.phone, '1234567890');\r\n      expect(branch.imageUrl, 'http://image.com');\r\n      expect(branch.openingHours, {'Monday': '09:00-18:00'});\r\n\r\n      final serialized = branch.toMap();\r\n      expect(serialized['name'], 'Downtown StyleHub');\r\n      expect(serialized['city'], 'New York');\r\n      expect(serialized['address'], '123 Main St');\r\n      expect(serialized['phone'], '1234567890');\r\n      expect(serialized['imageUrl'], 'http://image.com');\r\n      expect(serialized['openingHours'], {'Monday': '09:00-18:00'});\r\n    });\r\n\r\n    test('copyWith updates fields correctly', () {\r\n      const branch = BranchModel(\r\n        id: '1',\r\n        name: 'Old Name',\r\n        city: 'Old City',\r\n        address: 'Old Address',\r\n        phone: '111',\r\n      );\r\n\r\n      final updated = branch.copyWith(name: 'New Name', phone: '222');\r\n\r\n      expect(updated.id, '1');\r\n      expect(updated.name, 'New Name');\r\n      expect(updated.city, 'Old City');\r\n      expect(updated.address, 'Old Address');\r\n      expect(updated.phone, '222');\r\n    });\r\n  });\r\n}\r\n
